 95	  orgId: OrgId,
 96	  scope: ArchiveScope = {},
 97	): Promise<number> {
 98	  const row = getDb()
 99	    .select({ value: count() })
100	    .from(projects)
101	    .where(
102	      and(
103	        ...compact(
104	          orgPredicate(projects.orgId, orgId),
105	          livePredicate(projects.archivedAt, scope),
106	        ),
107	      ),
108	    )
109	    .get();
110	  return row?.value ?? 0;
111	}
