113	export async function insertProject(
114	  input: CreateProjectInput,
115	): Promise<Project> {
116	  const taken = await listTakenProjectSlugs(input.orgId);
117	  const slug = uniqueSlug(input.slug, taken);
118	  const stamp = toIsoTimestamp(new Date());
119	
120	  const row = getDb()
121	    .insert(projects)
122	    .values({
123	      id: newId(),
124	      orgId: input.orgId,
125	      name: input.name,
126	      slug,
127	      key: input.key,
128	      description: input.description,
129	      visibility: input.visibility,
130	      status: "active",
131	      leadId: input.leadId,
132	      color: input.color,
133	      startsAt: null,
134	      targetDate: input.targetDate,
135	      createdAt: stamp,
136	      updatedAt: stamp,
137	    })
138	    .returning()
139	    .get();
140	
141	  return toProject(row);
142	}
