144	export async function updateProject(
145	  input: UpdateProjectInput,
146	): Promise<Project> {
147	  const row = getDb()
148	    .update(projects)
149	    .set({
150	      ...(input.name === undefined ? {} : { name: input.name }),
151	      ...(input.description === undefined
152	        ? {}
153	        : { description: input.description }),
154	      ...(input.visibility === undefined
155	        ? {}
156	        : { visibility: input.visibility }),
157	      ...(input.status === undefined ? {} : { status: input.status }),
158	      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),
159	      ...(input.color === undefined ? {} : { color: input.color }),
160	      ...(input.targetDate === undefined
161	        ? {}
162	        : { targetDate: input.targetDate }),
163	      updatedAt: toIsoTimestamp(new Date()),
164	    })
165	    .where(
166	      and(
167	        orgPredicate(projects.orgId, input.orgId),
168	        eq(projects.id, input.projectId),
169	      ),
170	    )
171	    .returning()
172	    .get();
