208	/** Includes archived slugs — a restored project must not collide. */
209	export async function listTakenProjectSlugs(
210	  orgId: OrgId,
211	): Promise<readonly string[]> {
212	  const rows = getDb()
213	    .select({ slug: projects.slug })
214	    .from(projects)
215	    .where(orgPredicate(projects.orgId, orgId))
216	    .all();
