/* Scratch verification for the archived-project freeze. Removed after the run. */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let orgId: string;
let frozenId: string;
let liveId: string;
let doomedId: string;
let siblingIssueId: string;
let commentId: string;
let attachmentId: string;
const events: string[] = [];
const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
  tenant = await createTenant("freeze");
  await usageRepo.recomputeUsage(tenant.org.id);
  orgId = tenant.org.id;
  const owner = tenant.actors.owner;

  const frozen = await projectService.createProject(owner, {
    orgId, name: "Frozen", slug: "frozen", key: "FRZ", description: null,
    visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
  });
  frozenId = frozen.id;

  const sibling = await projectService.createProject(owner, {
    orgId, name: "Sibling", slug: "sibling", key: "SIB", description: null,
    visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
  });
  const siblingIssue = await issueService.createIssue(
    owner,
    issueInput(orgId, sibling.id, { title: "Sibling late", dueAt: PAST }),
  );
  siblingIssueId = siblingIssue.id;

  const live = await issueService.createIssue(
    owner,
    issueInput(orgId, frozen.id, { title: "Frozen issue", dueAt: PAST }),
  );
  liveId = live.id;

  const doomed = await issueService.createIssue(
    owner,
    issueInput(orgId, frozen.id, { title: "Doomed" }),
  );
  doomedId = doomed.id;
  await issueService.archiveIssue(owner, orgId, doomed.id);

  const comment = await commentService.createComment(owner, {
    orgId, issueId: live.id, body: "before freeze", parentId: null, mentionedUserIds: [],
  });
  commentId = comment.id;

  const attachment = await attachmentService.addAttachment(owner, {
    orgId, issueId: live.id, filename: "spec.pdf", contentType: "application/pdf", sizeBytes: 1024,
  });
  attachmentId = attachment.id;

  await projectService.archiveProject(owner, {
    orgId, projectId: frozen.id, archiveIssues: false,
  });

  for (const name of [
    "issue.created", "issue.updated", "issue.status_changed", "issue.assigned",
    "issue.archived", "comment.created", "comment.deleted",
  ] as const) {
    subscribe(name, () => {
      events.push(name);
    });
  }
  events.length = 0;
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  events.length = 0;
});

describe("archived project freeze", () => {
  const owner = () => tenant.actors.owner;

  it("refuses to edit an issue, changing nothing and publishing nothing", async () => {
    await expect(
      issueService.updateIssue(owner(), { orgId, issueId: liveId, title: "Renamed" } as never),
    ).rejects.toMatchObject({ entity: "Project" });
    await expect(
      issueService.updateIssue(owner(), { orgId, issueId: liveId, title: "Renamed" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await issueRepo.findIssueById(orgId, liveId as never))?.title).toBe("Frozen issue");
    expect(events).toEqual([]);
  });

  it("refuses status changes and board moves", async () => {
    await expect(
      issueService.changeIssueStatus(owner(), { orgId, issueId: liveId, status: "done" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.moveIssue(owner(), { orgId, issueId: liveId, toStatus: "done" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await issueRepo.findIssueById(orgId, liveId as never))?.status).toBe("backlog");
    expect(events).toEqual([]);
  });

  it("refuses to assign and to un-assign", async () => {
    await expect(
      issueService.assignIssue(owner(), { orgId, issueId: liveId, assigneeId: tenant.userIds.member } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.assignIssue(owner(), { orgId, issueId: liveId, assigneeId: null } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await issueRepo.findIssueById(orgId, liveId as never))?.assigneeId).toBeNull();
    expect(events).toEqual([]);
  });

  it("refuses to archive the issue", async () => {
    await expect(
      issueService.archiveIssue(owner(), orgId, liveId as never),
    ).rejects.toMatchObject({ entity: "Project" });
    expect((await issueRepo.findIssueById(orgId, liveId as never))?.archivedAt).toBeNull();
    expect(events).toEqual([]);
  });

  it("refuses to post, edit and delete comments", async () => {
    await expect(
      commentService.createComment(owner(), {
        orgId, issueId: liveId, body: "late", parentId: null, mentionedUserIds: [],
      } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      commentService.updateComment(owner(), { orgId, commentId, body: "edited" } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      commentService.deleteComment(owner(), { orgId, commentId } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    const row = await commentRepo.findCommentById(orgId, commentId as never);
    expect(row?.body).toBe("before freeze");
    expect(row?.archivedAt).toBeNull();
    expect(events).toEqual([]);
  });

  it("refuses to add and remove attachments", async () => {
    await expect(
      attachmentService.addAttachment(owner(), {
        orgId, issueId: liveId, filename: "b.pdf", contentType: "application/pdf", sizeBytes: 1024,
      } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      attachmentService.removeAttachment(owner(), { orgId, attachmentId } as never),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    const rows = await attachmentRepo.listAttachments(orgId, liveId as never);
    expect(rows.map((row) => row.id)).toEqual([attachmentId]);
  });

  it("keeps reads working", async () => {
    await expect(issueService.getIssue(owner(), orgId, liveId as never)).resolves.toMatchObject({
      issue: { id: liveId },
    });
    const page = await issueService.listIssues(owner(), {
      orgId, limit: 25, cursor: null, projectId: frozenId,
    } as never);
    expect(page.items.map((issue) => issue.id)).toContain(liveId);
    const board = await issueService.getBoard(owner(), orgId, frozenId as never);
    expect(board.flatMap((column) => column.issues.map((issue) => issue.id))).toContain(liveId);
    const thread = await commentService.getThread(owner(), orgId, liveId as never);
    expect(thread.length).toBeGreaterThan(0);
    const attachments = await attachmentService.listAttachments(owner(), orgId, liveId as never);
    expect(attachments.map((a) => a.id)).toContain(attachmentId);
  });

  it("reports a missing permission before the freeze", async () => {
    await expect(
      issueService.updateIssue(tenant.actors.viewer, { orgId, issueId: liveId, title: "x" } as never),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("an archived issue still reports itself", async () => {
    await expect(
      issueService.updateIssue(owner(), { orgId, issueId: doomedId, title: "x" } as never),
    ).rejects.toMatchObject({ entity: "Issue" });
    await expect(
      issueService.archiveIssue(owner(), orgId, doomedId as never),
    ).rejects.toMatchObject({ entity: "Issue" });
  });

  it("the overdue sweep skips the frozen issue but announces live ones", async () => {
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });
    try {
      await runOverdueIssueJob(NOW);
    } finally {
      off();
    }
    expect(seen).toEqual([siblingIssueId]);
  });

  it("restoring the project lifts the freeze", async () => {
    await projectService.restoreProject(owner(), orgId, frozenId as never);

    await expect(
      issueService.updateIssue(owner(), { orgId, issueId: liveId, title: "Renamed" } as never),
    ).resolves.toMatchObject({ title: "Renamed" });
    await expect(
      commentService.createComment(owner(), {
        orgId, issueId: liveId, body: "after restore", parentId: null, mentionedUserIds: [],
      } as never),
    ).resolves.toMatchObject({ body: "after restore" });
    await expect(
      attachmentService.addAttachment(owner(), {
        orgId, issueId: liveId, filename: "c.pdf", contentType: "application/pdf", sizeBytes: 1024,
      } as never),
    ).resolves.toMatchObject({ filename: "c.pdf" });
  });

  it("the overdue sweep announces the restored issue once", async () => {
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });
    try {
      await runOverdueIssueJob(NOW);
      await runOverdueIssueJob(NOW);
    } finally {
      off();
    }
    expect(seen).toEqual([liveId]);
  });
});

